SET NAMES utf8mb4;
CREATE TABLE establishments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,category VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,address VARCHAR(255) NOT NULL DEFAULT '',description TEXT,logo VARCHAR(255),active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE establishment_settings (establishment_id BIGINT UNSIGNED PRIMARY KEY,min_notice INT NOT NULL DEFAULT 60,max_days INT NOT NULL DEFAULT 60,slot_step INT NOT NULL DEFAULT 15,auto_confirm TINYINT NOT NULL DEFAULT 1,cancelled_releases TINYINT NOT NULL DEFAULT 1,message_template TEXT,FOREIGN KEY(establishment_id) REFERENCES establishments(id),CHECK(min_notice>=0 AND max_days BETWEEN 1 AND 365 AND slot_step BETWEEN 5 AND 120)) ENGINE=InnoDB;
CREATE TABLE professionals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,specialty VARCHAR(190) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1,deleted_at DATETIME NULL,UNIQUE(establishment_id,id),FOREIGN KEY(establishment_id) REFERENCES establishments(id)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NULL,professional_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('superadmin','admin','professional') NOT NULL,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(establishment_id) REFERENCES establishments(id),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),CHECK((role='superadmin' AND establishment_id IS NULL AND professional_id IS NULL) OR (role='admin' AND establishment_id IS NOT NULL AND professional_id IS NULL) OR (role='professional' AND establishment_id IS NOT NULL AND professional_id IS NOT NULL))) ENGINE=InnoDB;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,duration INT NOT NULL,buffer INT NOT NULL DEFAULT 0,image VARCHAR(255),active TINYINT NOT NULL DEFAULT 1,deleted_at DATETIME NULL,UNIQUE(establishment_id,id),FOREIGN KEY(establishment_id) REFERENCES establishments(id),CHECK(price>=0 AND duration BETWEEN 5 AND 720 AND buffer BETWEEN 0 AND 240)) ENGINE=InnoDB;
CREATE TABLE professional_services (establishment_id BIGINT UNSIGNED NOT NULL,professional_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(establishment_id,professional_id,service_id),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),FOREIGN KEY(establishment_id,service_id) REFERENCES services(establishment_id,id)) ENGINE=InnoDB;
CREATE TABLE business_hours (establishment_id BIGINT UNSIGNED NOT NULL,weekday TINYINT NOT NULL,opens TIME NOT NULL,closes TIME NOT NULL,closed TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(establishment_id,weekday),FOREIGN KEY(establishment_id) REFERENCES establishments(id),CHECK(weekday BETWEEN 0 AND 6 AND opens<closes)) ENGINE=InnoDB;
CREATE TABLE professional_working_hours (establishment_id BIGINT UNSIGNED NOT NULL,professional_id BIGINT UNSIGNED NOT NULL,weekday TINYINT NOT NULL,opens TIME NOT NULL,closes TIME NOT NULL,closed TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(establishment_id,professional_id,weekday),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),CHECK(weekday BETWEEN 0 AND 6 AND opens<closes)) ENGINE=InnoDB;
CREATE TABLE breaks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,professional_id BIGINT UNSIGNED NULL,weekday TINYINT NOT NULL,starts TIME NOT NULL,ends TIME NOT NULL,FOREIGN KEY(establishment_id) REFERENCES establishments(id),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),CHECK(weekday BETWEEN 0 AND 6 AND starts<ends),INDEX(establishment_id,weekday)) ENGINE=InnoDB;
CREATE TABLE schedule_exceptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,professional_id BIGINT UNSIGNED NULL,date DATE NOT NULL,closed TINYINT NOT NULL DEFAULT 1,opens TIME NULL,closes TIME NULL,reason VARCHAR(190) NOT NULL DEFAULT '',FOREIGN KEY(establishment_id) REFERENCES establishments(id),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),CHECK(closed=1 OR (opens IS NOT NULL AND closes IS NOT NULL AND opens<closes)),INDEX(establishment_id,date)) ENGINE=InnoDB;
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(190) NOT NULL DEFAULT '',UNIQUE(establishment_id,id),UNIQUE(establishment_id,phone),FOREIGN KEY(establishment_id) REFERENCES establishments(id)) ENGINE=InnoDB;
CREATE TABLE appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,client_id BIGINT UNSIGNED NOT NULL,professional_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,busy_until DATETIME NOT NULL,price DECIMAL(10,2) NOT NULL,status ENUM('pending','confirmed','completed','cancelled','no_show') NOT NULL,token CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(establishment_id,client_id) REFERENCES clients(establishment_id,id),FOREIGN KEY(establishment_id,professional_id) REFERENCES professionals(establishment_id,id),FOREIGN KEY(establishment_id,service_id) REFERENCES services(establishment_id,id),UNIQUE(establishment_id,id),INDEX(establishment_id,professional_id,starts_at,busy_until),CHECK(starts_at<ends_at AND ends_at<=busy_until)) ENGINE=InnoDB;
CREATE TABLE appointment_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,establishment_id BIGINT UNSIGNED NOT NULL,appointment_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,user_id BIGINT UNSIGNED NULL,note VARCHAR(255) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(establishment_id) REFERENCES establishments(id),FOREIGN KEY(establishment_id,appointment_id) REFERENCES appointments(establishment_id,id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY,hits INT NOT NULL,expires_at DATETIME NOT NULL,INDEX(expires_at)) ENGINE=InnoDB;
